contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address bt,
        address nftAddr,
        uint128 vBase,
        uint128 vNft,
        uint56 chgFee,
        uint16 feeRate,
        bytes32 root,
        bool useOracle,
        bool payRoy
    ) public {
        require(feeRate <= 5000);

        // first initialize must succeed and store parameters
        c.initialize(bt, nftAddr, vBase, vNft, chgFee, feeRate, root, useOracle, payRoy);

        // second initialize must revert
        bool reverted;
        try c.initialize(bt, nftAddr, vBase, vNft, chgFee, feeRate, root, useOracle, payRoy) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted
            && c.initialized()
            && c.baseToken() == bt
            && c.nft() == nftAddr
            && c.virtualBaseTokenReserves() == vBase
            && c.virtualNftReserves() == vNft
            && c.changeFee() == chgFee
            && c.feeRate() == feeRate
            && c.merkleRoot() == root
            && c.useStolenNftOracle() == useOracle
            && c.payRoyalties() == payRoy
        );
    }

    receive() external payable {}
}

