contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address nftAddress,
        uint128 vBase,
        uint128 vNft,
        uint16 feeRate,
        uint256 outputAmount
    ) public {
        require(vBase > 0);
        require(vNft >= 2e18);
        require(vNft <= 1e24);
        require(outputAmount >= 1);
        require(outputAmount < vNft);

        c.initialize(address(0), nftAddress, vBase, vNft, 0, feeRate, bytes32(0), false, false);

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(outputAmount);

        uint256 denominator = uint256(vNft) - outputAmount;
        uint256 expectedInput = (outputAmount * uint256(vBase) + denominator - 1) / denominator;

        assert(
            netInputAmount == expectedInput + feeAmount + protocolFeeAmount
        );
    }

    receive() external payable {}
}

