contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint16 _feeRate,
        uint256 _outputAmount
    ) public {
        require(_feeRate <= 5000);
        require(_virtualNftReserves > 0);
        require(_outputAmount > 0 && _outputAmount < _virtualNftReserves);
        require(_virtualBaseTokenReserves < 1e24);
        require(_virtualNftReserves < 1e24);

        c.initialize(
            address(0),
            address(0),
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            0,
            _feeRate,
            bytes32(0),
            false,
            false
        );

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.buyQuote(_outputAmount);

        // inputAmount = netInputAmount - feeAmount - protocolFeeAmount must equal netInput * 10000 / (10000 + feeRate)
        // exactly, and feeAmount must equal inputAmount * feeRate / 10000.
        assert(
            netInputAmount >= feeAmount + protocolFeeAmount &&
            feeAmount * 10000 == (netInputAmount - feeAmount - protocolFeeAmount) * _feeRate
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint16 _feeRate,
        uint256 _inputAmount
    ) public {
        require(_feeRate <= 5000);
        require(_virtualNftReserves > 0);
        require(_virtualBaseTokenReserves > 0);
        require(_inputAmount > 0 && _inputAmount <= 1e30);
        require(_virtualBaseTokenReserves <= 1e30);

        c.initialize(
            address(0),
            address(0),
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            0,
            _feeRate,
            bytes32(0),
            false,
            false
        );

        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(_inputAmount);

        // gross output minus both fees equals the net output, and both fees are
        // exactly proportional to the gross output with the pool's feeRate and
        // the factory protocol fee rate (0 here).
        assert(
            netOutputAmount == _virtualBaseTokenReserves * _inputAmount / (_virtualNftReserves + _inputAmount)
                - feeAmount
            && protocolFeeAmount == 0
            && feeAmount * 10000 == (_virtualBaseTokenReserves * _inputAmount / (_virtualNftReserves + _inputAmount)) * _feeRate
        );
    }
}

