contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint16 newFeeRate) public {
        uint16 before = c.feeRate();
        bool reverted;
        try c.setFeeRate(newFeeRate) { reverted = false; } catch { reverted = true; }
        if (!reverted) {
            assert(newFeeRate <= 5_000 && c.feeRate() == newFeeRate);
        } else {
            assert(c.feeRate() == before);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256[] memory tokenIds, uint256[][] memory tokenWeights) public {
        require(tokenIds.length == tokenWeights.length);
        require(tokenIds.length > 0);
        bool rootIsZero = c.merkleRoot() == bytes32(0);
        uint256 result = c.sumWeightsAndValidateProof(tokenIds, tokenWeights[0], C.MerkleMultiProof(new bytes32[](0), new bool[](0)));
        if (rootIsZero) {
            assert(result == tokenIds.length * 1e18);
        } else {
            assert(result >= 0);
        }
    }
    receive() external payable {}
}

